<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Plus,Search} from '@element-plus/icons-vue'
import ImageUpload from '../components/ImageUpload.vue'
import {api,get,post,useTask,number} from '../api/client'
const persons=ref<any[]>([]),query=ref(''),dialog=ref(false),detail=ref<any>(null),edit=ref<any>(null)
const name=ref(''),note=ref(''),capture=ref(''),files=ref<File[]>([])
const {busy,run}=useTask()
async function load(){persons.value=await get('/person?q='+encodeURIComponent(query.value))}
onMounted(()=>run(load))
function create(){if(!name.value.trim()||!capture.value.trim()||!files.value.length){ElMessage.warning('请填写姓名、采集会话编号并上传照片');return}run(async()=>{const form=new FormData();form.append('name',name.value);form.append('note',note.value);form.append('capture_id',capture.value);files.value.forEach(f=>form.append('files',f));await post('/person/register',form);dialog.value=false;name.value='';note.value='';capture.value='';files.value=[];await load();ElMessage.success('身份已注册，特征保存在本地')})}
async function remove(row:any){try{await ElMessageBox.confirm(`删除“${row.name}”及全部参考照片、特征和关联查询记录？历史实验标签保留为编号。`,'删除身份',{type:'warning'});await run(async()=>{await api.delete('/person/'+row.id);await load()})}catch{/* user cancelled */}}
</script>
<template><section class="card"><div class="toolbar"><div><h2>已注册身份 <span class="count-badge">{{persons.length}}</span></h2><p class="muted">多参考照片注册 · 归一化特征 · 余弦相似度</p></div><div class="toolbar-actions"><el-input v-model="query" placeholder="搜索姓名" :prefix-icon="Search" clearable @input="run(load)"/><el-button type="primary" :icon="Plus" @click="dialog=true">注册新身份</el-button></div></div><el-table :data="persons" v-loading="busy" empty-text="身份库为空，点击“注册新身份”开始"><el-table-column prop="id" label="编号" width="80"/><el-table-column label="人员姓名" min-width="130"><template #default="{row}"><div class="person-name"><span class="person-avatar" aria-hidden="true">{{row.name.slice(0,1)}}</span><span>{{row.name}}</span></div></template></el-table-column><el-table-column prop="sample_count" label="参考样本" width="110"/><el-table-column prop="note" label="备注" min-width="160"/><el-table-column label="注册时间" min-width="180"><template #default="{row}">{{new Date(row.created_at+'Z').toLocaleString('zh-CN')}}</template></el-table-column><el-table-column label="操作" width="200"><template #default="{row}"><el-button link type="primary" @click="run(async()=>{detail=await get('/person/'+row.id)})">查看</el-button><el-button link @click="edit={...row}">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div class="note">注册照片须恰有一张可检测人脸。请为同一采集会话使用一致编号；校准和测试使用独立会话。照片仅保存在本机。</div></section>
<el-dialog v-model="dialog" title="注册新身份" width="560px" destroy-on-close :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="姓名"><el-input v-model="name" maxlength="80"/></el-form-item><el-form-item label="采集会话编号"><el-input v-model="capture" maxlength="120" placeholder="例如 enroll-20261016-session01"/></el-form-item><el-form-item label="备注"><el-input v-model="note" maxlength="500" type="textarea"/></el-form-item><el-form-item label="参考照片（1–10 张，原始图像注册）"><ImageUpload multiple @change="value=>files=value"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="create">提取特征并注册</el-button></template></el-dialog>
<el-dialog :model-value="!!edit" title="编辑身份" width="460px" @close="edit=null"><el-form v-if="edit" label-position="top"><el-form-item label="姓名"><el-input v-model="edit.name" maxlength="80"/></el-form-item><el-form-item label="备注"><el-input v-model="edit.note" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" @click="run(async()=>{await api.patch('/person/'+edit.id,{name:edit.name,note:edit.note});edit=null;await load()})">保存修改</el-button></template></el-dialog>
<el-drawer :model-value="!!detail" title="身份与参考样本" size="540px" @close="detail=null"><template v-if="detail"><h2>{{detail.name}}</h2><p class="muted">{{detail.note || '暂无备注'}}</p><div v-for="sample in detail.samples" :key="sample.id" class="sample-detail"><img :src="sample.image_url" alt="注册参考照片"><div><h3>参考样本 #{{sample.id}}</h3><p>{{sample.dimensions}} 维归一化特征</p><p>平均亮度 {{number(sample.quality.mean_brightness)}} · 清晰度 {{number(sample.quality.sharpness)}}</p><p class="muted">会话：{{sample.capture_id}}</p><el-tag size="small" type="success">检测置信度 {{number(sample.quality.detection_confidence,3)}}</el-tag></div></div><p class="muted">特征向量不通过普通查询接口公开。</p></template></el-drawer></template>
